  if(asset.group==='boulders'||asset.group==='lights')return [asset.name+' physically accurate overhead asset at X '+fmt(o.x)+'m Y '+fmt(o.y)+'m'+
   (asset.group==='lights'?' / fixture '+asset.id+' / height '+fmt(o.height)+' m / rotation '+fmt(o.rotation)+'° / '+(Number(o.kelvin)||2700)+' K / intensity '+fmt(o.brightness??1):'')];
