 const height=num(v.bladeHeightM,.005,1.4,.06),density=num(v.densityPercent,45,160,100),pressed=num(v.pressedPercent,0,100,45),flowers=num(v.flowerPercent,0,100,75);
 const flowering=['clover','dandelion','dandelionPuff'].includes(v.profile);
